"""Marchés et instruments : actions, ETF, contrats à terme, change, crypto, organisation des marchés."""
from __future__ import annotations

from patrick.knowledge.dictionary import d

T = "marches"
TERMS = [
    d(T, "marche_primaire_secondaire", "Marché primaire et marché secondaire", "Primary and secondary market", 1,
      "Sur le marché primaire, une entreprise ou un État émet de nouveaux titres et reçoit l'argent ; sur le marché secondaire, les investisseurs se revendent des titres déjà émis, sans que l'émetteur n'encaisse rien. La bourse au quotidien est du secondaire.",
      "On the primary market a company or state issues new securities and receives the money; on the secondary market investors resell existing securities to each other, with no cash to the issuer. Day-to-day trading is secondary.",
      see="introduction_en_bourse bourse"),
    d(T, "introduction_en_bourse", "Introduction en bourse (IPO)", "Initial public offering (IPO)", 2,
      "Première cotation d'une entreprise : elle vend une partie de son capital au public pour se financer. Les introductions sont souvent sous-évaluées le premier jour puis décevantes à trois ans, et leur historique de prix est court.",
      "A company's first listing: it sells part of its capital to the public to raise funds. IPOs are often underpriced on day one and then disappoint over three years, and their price history is short.",
      see="marche_primaire_secondaire flottant", alias="IPO"),
    d(T, "flottant", "Flottant (free float)", "Free float", 2,
      "Part des actions réellement disponibles à l'échange, hors blocs détenus durablement par des actionnaires de contrôle ou l'État. Beaucoup d'indices pondèrent par la capitalisation flottante plutôt que totale.",
      "Share of the stock actually available for trading, excluding blocks held long-term by controlling shareholders or the state. Many indices weight by free-float rather than total market cap.",
      see="capitalisation_boursiere indice_boursier", alias="free float"),
    d(T, "split_regroupement", "Division et regroupement d'actions (split)", "Stock split and reverse split", 1,
      "Un split divise chaque action en plusieurs (1 en 4) et divise le cours d'autant, sans changer la valeur de l'entreprise ; un regroupement fait l'inverse. Les cours historiques doivent être ajustés, sinon le split ressemble à un krach.",
      "A split divides each share into several (1 into 4) and divides the price accordingly, without changing the company's value; a reverse split does the opposite. Historical prices must be adjusted, otherwise a split looks like a crash.",
      see="cours_ajuste dividende", alias="split"),
    d(T, "rachat_actions", "Rachat d'actions", "Share buyback", 2,
      "L'entreprise rachète ses propres actions avec sa trésorerie : le nombre d'actions baisse, le bénéfice par action monte. C'est une façon de rendre de l'argent aux actionnaires alternative au dividende.",
      "The company buys back its own shares with cash: the share count falls and earnings per share rise. It is a way to return cash to shareholders as an alternative to dividends.",
      see="dividende bpa"),
    d(T, "adr", "ADR (certificat de dépôt américain)", "ADR (American depositary receipt)", 2,
      "Certificat négocié aux États-Unis, en dollars, qui représente des actions d'une société étrangère (Toyota, SAP, Novo Nordisk). Son cours suit l'action locale mais inclut le risque de change et peut décaler d'horaires.",
      "Certificate traded in the US, in dollars, representing shares of a foreign company (Toyota, SAP, Novo Nordisk). Its price follows the local share but includes currency risk and may differ in trading hours.",
      see="devise_change"),
    d(T, "reit_siic", "Foncière cotée (REIT, SIIC)", "Listed real-estate company (REIT)", 2,
      "Société cotée qui possède et loue des immeubles et doit distribuer l'essentiel de ses revenus. Elle donne une exposition à l'immobilier avec la liquidité d'une action, mais en subit la volatilité et la sensibilité aux taux.",
      "Listed company owning and renting buildings that must pay out most of its income. It gives real-estate exposure with stock-like liquidity, but also stock-like volatility and rate sensitivity.",
      see="taux_interet rendement_dividende", alias="REIT; SIIC"),
    d(T, "produit_structure", "Produit structuré", "Structured product", 3,
      "Instrument sur mesure, souvent une obligation associée à une ou plusieurs options, dont le gain dépend de conditions (capital garanti, barrière, coupon conditionnel). Il est complexe, peu liquide et ses frais sont cachés dans le prix.",
      "Bespoke instrument, often a bond bundled with options, whose payoff depends on conditions (guaranteed capital, barrier, conditional coupon). It is complex, illiquid, and its fees are hidden in the price.",
      see="option obligation"),
    d(T, "cfd", "CFD (contrat pour la différence)", "CFD (contract for difference)", 2,
      "Contrat par lequel on échange la différence de prix d'un actif entre l'ouverture et la clôture de la position, avec un fort levier, sans détenir l'actif. Risque élevé : la majorité des particuliers y perdent de l'argent, d'où des restrictions réglementaires.",
      "Contract exchanging the price difference of an asset between opening and closing a position, with high leverage, without owning the asset. High risk: most retail clients lose money, hence regulatory restrictions.",
      see="levier marge"),
    d(T, "future", "Contrat à terme (future)", "Futures contract", 2,
      "Contrat standardisé, négocié en bourse, d'acheter ou vendre un actif (indice, pétrole, taux, devise) à un prix fixé aujourd'hui pour une livraison future. Il est marqué au marché chaque jour et exige une marge ; il permet le levier et la vente à découvert sans emprunt.",
      "Standardised exchange-traded contract to buy or sell an asset (index, oil, rates, currency) at a price fixed today for future delivery. It is marked to market daily and requires margin; it allows leverage and shorting without borrowing.",
      see="forward contango_backwardation marge roll_contrat", alias="futures; contrat à terme"),
    d(T, "forward", "Contrat à terme de gré à gré (forward)", "Forward contract", 2,
      "Comme un future, mais sur mesure et négocié directement entre deux parties : pas de marché organisé, pas de marge quotidienne, donc un risque de contrepartie. Très utilisé pour couvrir le change.",
      "Like a future but bespoke and negotiated directly between two parties: no organised market, no daily margin, hence counterparty risk. Widely used to hedge currency.",
      see="future gre_a_gre_otc risque_contrepartie"),
    d(T, "contango_backwardation", "Contango et backwardation", "Contango and backwardation", 2,
      "Le marché est en contango quand les contrats lointains cotent plus cher que le comptant (coût de stockage et de financement) ; en backwardation quand ils cotent moins cher (pénurie immédiate). Cela détermine le gain ou la perte au roulement des contrats.",
      "A market is in contango when distant contracts trade above spot (storage and financing costs); in backwardation when they trade below (immediate scarcity). This sets the gain or loss when rolling contracts.",
      see="roll_contrat future cout_de_portage", alias="contango; backwardation"),
    d(T, "roll_contrat", "Roulement de contrat (roll)", "Contract roll", 2,
      "Un future expire : pour garder une position, on le remplace avant l'échéance par le contrat suivant. L'écart de prix entre les deux crée un rendement (ou un coût) de roulement, et l'historique d'une série continue doit être raccordé avec soin.",
      "A future expires: to keep a position, one replaces it before expiry with the next contract. The price gap between the two creates a roll yield (or cost), and a continuous series history must be spliced carefully.",
      see="contango_backwardation future serie_continue"),
    d(T, "gre_a_gre_otc", "Marché de gré à gré (OTC)", "Over-the-counter market (OTC)", 2,
      "Marché sans bourse centrale, où deux parties négocient directement : change, swaps, la plupart des obligations. Moins transparent, avec des prix propres à chaque intermédiaire et un risque de contrepartie.",
      "Market with no central exchange, where two parties trade directly: currencies, swaps, most bonds. Less transparent, with prices specific to each dealer and counterparty risk.",
      see="forward risque_contrepartie chambre_de_compensation", alias="OTC"),
    d(T, "chambre_de_compensation", "Chambre de compensation", "Clearing house", 3,
      "Intermédiaire qui s'interpose entre acheteur et vendeur d'un contrat dérivé : il devient la contrepartie de chacun, exige des marges et mutualise les défauts. Elle remplace le risque de contrepartie bilatéral par un risque sur la chambre.",
      "Intermediary standing between buyer and seller of a derivative: it becomes each side's counterparty, demands margin and pools defaults. It replaces bilateral counterparty risk with risk on the clearing house.",
      see="future risque_contrepartie"),
    d(T, "sessions_horaires", "Sessions de marché", "Trading sessions", 1,
      "Une bourse a une séance principale (par exemple 9 h–17 h 30 à Paris, 9 h 30–16 h à New York), des enchères d'ouverture et de clôture, et parfois des séances avant et après ouverture, moins liquides. Les heures sont locales : attention aux fuseaux horaires.",
      "An exchange has a main session (for example 9:00–17:30 in Paris, 9:30–16:00 in New York), opening and closing auctions, and sometimes thinner pre- and after-market sessions. Hours are local: mind the time zones.",
      see="enchere_ouverture_cloture fuseau_horaire"),
    d(T, "enchere_ouverture_cloture", "Enchères d'ouverture et de clôture", "Opening and closing auctions", 2,
      "Phases où les ordres s'accumulent puis sont appariés à un prix unique qui maximise les volumes échangés. Le cours de clôture, référence des indices et des fonds, naît de cette enchère et concentre une grande part du volume.",
      "Phases where orders accumulate then are matched at a single price maximising traded volume. The closing price, the reference for indices and funds, is born of this auction and concentrates a large share of volume.",
      see="sessions_horaires"),
    d(T, "fuseau_horaire", "Fuseaux horaires et calendrier de bourse", "Time zones and trading calendar", 2,
      "Les marchés ferment à des heures et des jours différents (jours fériés propres à chaque pays). Aligner deux séries de pays différents exige de comparer des clôtures qui n'ont pas lieu au même instant : une source classique de fausse corrélation décalée.",
      "Markets close at different hours and days (national holidays). Aligning series from different countries means comparing closes that do not occur at the same moment: a classic source of spurious lagged correlation.",
      see="sessions_horaires alignement_temporel"),
    d(T, "circuit_breaker", "Coupe-circuit (circuit breaker)", "Circuit breaker", 2,
      "Suspension automatique de la cotation quand un cours ou un indice bouge de plus d'un seuil en peu de temps, pour laisser le marché reprendre ses esprits. Les prix observés autour de ces arrêts sont peu représentatifs.",
      "Automatic trading halt when a price or index moves beyond a threshold in a short time, to let the market cool down. Prices around such halts are not very representative.",
      see="krach"),
    d(T, "dark_pool", "Plateforme opaque (dark pool)", "Dark pool", 3,
      "Lieu d'échange où les ordres ne sont pas affichés avant exécution, utilisé par les grands investisseurs pour éviter de faire bouger le prix. Il fragmente la liquidité et réduit la transparence pré-négociation.",
      "Trading venue where orders are not displayed before execution, used by large investors to avoid moving the price. It fragments liquidity and reduces pre-trade transparency.",
      see="impact_de_marche carnet_ordres"),
    d(T, "etf_physique_synthetique", "ETF physique et ETF synthétique", "Physical and synthetic ETF", 2,
      "Un ETF physique détient réellement les titres de l'indice ; un ETF synthétique le réplique par un contrat d'échange (swap) avec une banque. Le second suit parfois mieux les indices difficiles d'accès, mais ajoute un risque de contrepartie.",
      "A physical ETF actually holds the index securities; a synthetic ETF replicates it through a swap with a bank. The latter sometimes tracks hard-to-access indices better but adds counterparty risk.",
      see="etf risque_contrepartie swap_taux"),
    d(T, "tracking_difference", "Écart de suivi (tracking difference)", "Tracking difference", 2,
      "Écart de performance cumulée entre un fonds et son indice sur une période, dû surtout aux frais de gestion, aux frictions de réplication et à la fiscalité des dividendes. Il se distingue de la tracking error, qui est la volatilité de cet écart.",
      "Cumulative performance gap between a fund and its index over a period, mostly due to management fees, replication frictions and dividend taxation. It differs from tracking error, which is the volatility of that gap.",
      see="etf tracking_error"),
    d(T, "etn", "ETN (titre indiciel émis par une banque)", "ETN (exchange-traded note)", 2,
      "Dette non garantie d'une banque dont le remboursement est indexé sur un indice ou un actif. Contrairement à un ETF, il porte le risque de défaut de l'émetteur.",
      "Unsecured debt of a bank whose repayment is indexed to an index or asset. Unlike an ETF, it carries the issuer's default risk.",
      see="etf risque_contrepartie"),
    d(T, "vix_indice", "Indice VIX", "VIX index", 2,
      "Indice de volatilité implicite à 30 jours des options sur le S&P 500, souvent appelé « indice de la peur ». Il monte quand les investisseurs achètent de la protection ; environ 15–20 en temps calme, 40 et plus en crise. On ne l'achète pas directement : on passe par des futures ou des ETN.",
      "Index of 30-day implied volatility of S&P 500 options, often called the 'fear gauge'. It rises when investors buy protection; about 15–20 in calm times, 40 and above in a crisis. It cannot be bought directly: one uses futures or ETNs.",
      see="vol_implicite skew_vol variance_swap", alias="VIX; indice de la peur"),
    d(T, "secteurs_gics", "Secteurs (classification GICS)", "Sectors (GICS classification)", 1,
      "Classification mondiale des entreprises en 11 secteurs (énergie, technologie, santé, finance, consommation...), puis industries et sous-industries. Elle sert à comparer une entreprise à ses pairs et à repérer des expositions cachées.",
      "Global classification of companies into 11 sectors (energy, technology, health care, financials, consumer...), then industries and sub-industries. It is used to compare a company with peers and spot hidden exposures.",
      see="indice_boursier benchmark"),
    d(T, "paire_de_devises", "Paire de devises", "Currency pair", 1,
      "Cotation d'une devise contre une autre : dans EUR/USD, l'euro est la devise de base et le dollar la devise cotée. L'unité de variation est le pip (0,0001 pour la plupart des paires). Les paires majeures impliquent le dollar ; les autres sont des croisés.",
      "Quote of one currency against another: in EUR/USD the euro is the base currency and the dollar the quote currency. The unit of move is the pip (0.0001 for most pairs). Majors involve the dollar; the others are crosses.",
      see="devise_change carry_trade", alias="paire de devises; forex; FX"),
    d(T, "carry_trade", "Carry trade", "Carry trade", 3,
      "Emprunter dans une devise à taux bas pour placer dans une devise à taux haut, en encaissant l'écart de taux tant que le change ne bouge pas contre soi. Il gagne souvent doucement et perd brutalement lors des retournements de marché.",
      "Borrowing in a low-rate currency to invest in a high-rate one, collecting the rate gap as long as the exchange rate does not move against you. It often earns slowly and loses abruptly when markets reverse.",
      see="paire_de_devises taux_interet skewness", alias="portage"),
    d(T, "stablecoin", "Stablecoin", "Stablecoin", 2,
      "Crypto-actif conçu pour garder une valeur fixe (1 dollar), adossé à des réserves ou à un algorithme. Il sert de monnaie d'échange sur les plateformes ; son risque est celui des réserves et de la confiance (décrochage, ruée).",
      "Crypto-asset designed to hold a fixed value (1 dollar), backed by reserves or an algorithm. It acts as trading money on exchanges; its risk is that of the reserves and of confidence (depeg, run).",
      see="crypto_actif"),
    d(T, "swap_taux", "Swap de taux", "Interest-rate swap", 3,
      "Contrat où deux parties échangent des flux d'intérêts calculés sur un même nominal : l'une paie un taux fixe, l'autre un taux variable (SOFR, €STR, Euribor). Il sert à transformer une dette variable en fixe, ou l'inverse, et à couvrir le risque de taux.",
      "Contract in which two parties swap interest flows computed on the same notional: one pays a fixed rate, the other a floating rate (SOFR, €STR, Euribor). It converts floating debt to fixed or vice versa, and hedges rate risk.",
      see="taux_directeur duration dv01"),
    d(T, "warrant_certificat", "Warrant et certificat", "Warrant and certificate", 2,
      "Produits cotés à effet de levier : un warrant est une option émise par une banque ; un certificat réplique un sous-jacent ou une stratégie. Ils se négocient comme des actions mais comportent le risque de l'émetteur et, pour les warrants, une perte de valeur dans le temps.",
      "Leveraged listed products: a warrant is an option issued by a bank; a certificate replicates an underlying or strategy. They trade like shares but carry issuer risk and, for warrants, time decay.",
      see="option produit_structure"),
    d(T, "serie_continue", "Série continue de futures", "Continuous futures series", 3,
      "Chaîne de prix obtenue en raccordant des contrats successifs qui expirent. Selon la méthode (écart brut, ajustement par différence, par ratio), les rendements, les niveaux et les volatilités diffèrent : à choisir selon ce qu'on mesure.",
      "Price chain obtained by splicing successive expiring contracts. Depending on the method (raw gap, difference adjustment, ratio adjustment), returns, levels and volatilities differ: choose according to what one measures.",
      see="roll_contrat contango_backwardation"),
    d(T, "marche_emergent", "Marchés émergents et développés", "Emerging and developed markets", 1,
      "Les marchés développés (États-Unis, Europe, Japon) sont grands, liquides et bien régulés ; les émergents (Chine, Inde, Brésil...) croissent plus vite mais sont plus volatils, plus exposés au change et aux risques politiques et de liquidité.",
      "Developed markets (US, Europe, Japan) are large, liquid and well regulated; emerging ones (China, India, Brazil...) grow faster but are more volatile and more exposed to currency, political and liquidity risk.",
      see="devise_change risque_notion"),
]
